export class ParseError extends Error {}
const fail = (m) => { throw new ParseError(m) }

const newTable = () => ({ t: 'table', m: new Map(), hdr: false })
const isBare = (c) => c !== undefined && /[A-Za-z0-9_-]/.test(c)
const isWs = (c) => c === ' ' || c === '\t'
const isEnd = (c) => c === undefined || c === '#' || c === ';'

class Line {
  constructor(s) { this.s = s; this.i = 0 }
  get c() { return this.s[this.i] }
  ws() { while (isWs(this.c)) this.i++ }
}

function parseString(L) {
  const q = L.c
  L.i++
  let out = ''
  for (;;) {
    const c = L.c
    if (c === undefined) fail('unterminated string')
    L.i++
    if (c === q) return out
    if (q === "'" || c !== '\\') { out += c; continue }
    const e = L.c
    if (e === undefined) fail('unterminated string')
    L.i++
    if (e === '"') out += '"'
    else if (e === '\\') out += '\\'
    else if (e === 'n') out += '\n'
    else if (e === 't') out += '\t'
    else if (e === 'r') out += '\r'
    else if (e === '0') out += '\0'
    else if (e === 'u') {
      const h = L.s.substr(L.i, 4)
      if (!/^[0-9a-fA-F]{4}$/.test(h)) fail('invalid escape \\u')
      out += String.fromCharCode(parseInt(h, 16))
      L.i += 4
    } else {
      const cp = String.fromCodePoint(L.s.codePointAt(L.i - 1))
      fail('invalid escape \\' + cp)
    }
  }
}

function parseName(L) {
  const c = L.c
  if (c === '"' || c === "'") return parseString(L)
  if (!isBare(c)) fail('expected a name')
  const st = L.i
  while (isBare(L.c)) L.i++
  return L.s.slice(st, L.i)
}

function parseDotted(L) {
  const names = [parseName(L)]
  for (;;) {
    const save = L.i
    L.ws()
    if (L.c === '.') {
      L.i++
      L.ws()
      names.push(parseName(L))
    } else { L.i = save; return names }
  }
}

const INT = /^[+-]?\d+(_\d+)*$/
const FLOAT = /^[+-]?\d+(_\d+)*(\.\d+(_\d+)*)?([eE][+-]?\d+(_\d+)*)?$/

function parseValue(L, path) {
  const c = L.c
  if (c === '"' || c === "'") return { t: 'string', v: parseString(L) }
  if (c === '[') return parseArray(L, path)
  if (c === '{') return parseInline(L, path)
  if (isEnd(c) && c !== '#' || c === undefined || c === ',' || c === ']' || c === '}') fail('expected a value')
  if (c === ';') fail('expected a value')
  const st = L.i
  while (L.c !== undefined && !isWs(L.c) && !',]};'.includes(L.c)) L.i++
  const w = L.s.slice(st, L.i)
  if (w === 'true' || w === 'false') return { t: 'boolean', v: w === 'true' }
  if (INT.test(w)) return { t: 'integer', v: Number(w.replace(/_/g, '')) }
  if (FLOAT.test(w)) return { t: 'float', v: Number(w.replace(/_/g, '')) }
  fail('invalid value ' + w)
}

function parseArray(L, path) {
  L.i++
  const arr = { t: 'array', items: [], aot: false }
  let first = true
  for (;;) {
    L.ws()
    if (isEnd(L.c)) fail('unterminated array')
    if (L.c === ']' && (first || arr.comma)) { L.i++; return arr }
    arr.items.push(parseValue(L, path.concat('[' + arr.items.length + ']')))
    first = false
    arr.comma = false
    L.ws()
    if (L.c === ',') { L.i++; arr.comma = true; continue }
    if (L.c === ']') { L.i++; return arr }
    fail('unterminated array')
  }
}

function parseInline(L, path) {
  L.i++
  const tab = newTable()
  L.ws()
  if (L.c === '}') { L.i++; return tab }
  for (;;) {
    L.ws()
    if (isEnd(L.c)) fail('unterminated inline table')
    const names = parseDotted(L)
    L.ws()
    if (L.c !== '=') fail('expected = in an inline table')
    L.i++
    L.ws()
    const v = parseValue(L, path.concat(names))
    assign(tab, path, names, v)
    L.ws()
    if (L.c === ',') { L.i++; continue }
    if (L.c === '}') { L.i++; return tab }
    fail('unterminated inline table')
  }
}

const pstr = (p) => p.join('.')

function walk(tab, base, names, onFinalMissing) {
  let cur = tab
  const path = base.slice()
  for (let k = 0; k < names.length - 1; k++) {
    path.push(names[k])
    let n = cur.m.get(names[k])
    if (!n) { n = newTable(); cur.m.set(names[k], n) }
    if (n.t === 'array' && n.aot) n = n.items[n.items.length - 1]
    else if (n.t !== 'table') fail(pstr(path) + ' is not a table')
    cur = n
  }
  path.push(names[names.length - 1])
  return { cur, path }
}

function assign(tab, base, names, v) {
  const { cur, path } = walk(tab, base, names)
  const key = names[names.length - 1]
  if (cur.m.has(key)) fail('key ' + pstr(path) + ' is defined twice')
  cur.m.set(key, v)
}

export function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = newTable()
  let current = root
  let curPath = []
  for (let n = 0; n < lines.length; n++) {
    try {
      const L = new Line(lines[n])
      L.ws()
      if (L.c === undefined || L.c === '#' || L.c === ';') continue
      if (L.c === '[') {
        const aot = lines[n][L.i + 1] === '['
        L.i += aot ? 2 : 1
        L.ws()
        const names = parseDotted(L)
        L.ws()
        const close = (ch) => { if (L.c !== ch) fail('unterminated table header'); L.i++ }
        close(']')
        if (aot) close(']')
        L.ws()
        if (!isEnd(L.c)) fail('trailing text after a table header')
        const { cur, path } = walk(root, [], names)
        const key = names[names.length - 1]
        const ex = cur.m.get(key)
        if (aot) {
          let arr = ex
          if (!arr) { arr = { t: 'array', items: [], aot: true }; cur.m.set(key, arr) }
          else if (arr.t !== 'array' || !arr.aot) fail(pstr(path) + ' is not an array of tables')
          const t = newTable()
          arr.items.push(t)
          current = t
        } else {
          let t = ex
          if (!t) { t = newTable(); cur.m.set(key, t) }
          else if (t.t !== 'table') fail(pstr(path) + ' is not a table')
          else if (t.hdr) fail('table ' + pstr(path) + ' is defined twice')
          t.hdr = true
          current = t
        }
        curPath = path
        continue
      }
      const names = parseDotted(L)
      L.ws()
      if (L.c !== '=') fail('expected key = value')
      L.i++
      L.ws()
      const v = parseValue(L, curPath.concat(names))
      L.ws()
      if (!isEnd(L.c)) fail('trailing text after a value')
      assign(current, curPath, names, v)
    } catch (e) {
      if (e instanceof ParseError) e.message = 'line ' + (n + 1) + ': ' + e.message
      throw e
    }
  }
  return root
}
